var VERSES33=[[1, "믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거니", "Now faith is the assurance of things hoped for, the conviction of things not seen."], [2, "선진들이 이로써 증거를 얻었느니라", "For by it the people of old received their commendation."], [3, "믿음으로 모든 세계가 하나님의 말씀으로 지어진 줄을 우리가 아나니 보이는 것은 나타난 것으로 말미암아 된 것이 아니니라", "By faith we understand that the universe was created by the word of God, so that what is seen was not made out of things that are visible."], [4, "믿음으로 아벨은 가인보다 더 나은 제사를 하나님께 드림으로 의로운 자라 하시는 증거를 얻었으니 하나님이 그 예물에 대하여 증언하심이라 그가 죽었으나 그 믿음으로써 지금도 말하느니라", "By faith Abel offered to God a more acceptable sacrifice than Cain, through which he was commended as righteous, God commending him by accepting his gifts. And through his faith, though he died, he still speaks."], [5, "믿음으로 에녹은 죽음을 보지 않고 옮겨졌으니 하나님이 그를 옮기심으로 다시 보이지 아니하였느니라 그는 옮겨지기 전에 하나님을 기쁘시게 하는 자라 하는 증거를 받았느니라", "By faith Enoch was taken up so that he should not see death, and he was not found, because God had taken him. Now before he was taken he was commended as having pleased God."], [6, "믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라", "And without faith it is impossible to please him, for whoever would draw near to God must believe that he exists and that he rewards those who seek him.", 1]];
var BIBLE33={"heb": {"11": {"1": ["믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거니", "Now faith is the assurance of things hoped for, the conviction of things not seen."], "2": ["선진들이 이로써 증거를 얻었느니라", "For by it the people of old received their commendation."], "3": ["믿음으로 모든 세계가 하나님의 말씀으로 지어진 줄을 우리가 아나니 보이는 것은 나타난 것으로 말미암아 된 것이 아니니라", "By faith we understand that the universe was created by the word of God, so that what is seen was not made out of things that are visible."], "4": ["믿음으로 아벨은 가인보다 더 나은 제사를 하나님께 드림으로 의로운 자라 하시는 증거를 얻었으니 하나님이 그 예물에 대하여 증언하심이라 그가 죽었으나 그 믿음으로써 지금도 말하느니라", "By faith Abel offered to God a more acceptable sacrifice than Cain, through which he was commended as righteous, God commending him by accepting his gifts. And through his faith, though he died, he still speaks."], "5": ["믿음으로 에녹은 죽음을 보지 않고 옮겨졌으니 하나님이 그를 옮기심으로 다시 보이지 아니하였느니라 그는 옮겨지기 전에 하나님을 기쁘시게 하는 자라 하는 증거를 받았느니라", "By faith Enoch was taken up so that he should not see death, and he was not found, because God had taken him. Now before he was taken he was commended as having pleased God."], "6": ["믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라", "And without faith it is impossible to please him, for whoever would draw near to God must believe that he exists and that he rewards those who seek him."]}, "12": {"2": ["믿음의 주요 또 온전하게 하시는 이인 예수를 바라보자 그는 그 앞에 있는 기쁨을 위하여 십자가를 참으사 부끄러움을 개의치 아니하시더니 하나님 보좌 우편에 앉으셨느니라", "looking to Jesus, the founder and perfecter of our faith, who for the joy that was set before him endured the cross, despising the shame, and is seated at the right hand of the throne of God."]}}, "gen": {"5": {"24": ["에녹이 하나님과 동행하더니 하나님이 그를 데려 가시므로 세상에 있지 아니하였더라", "Enoch walked with God, and he was not, for God took him."]}}};
var LESSONS33={"mon": {"name": "마음 열기", "tag": "OPEN OUR HEARTS", "title": "말씀을 느껴요!", "en": "Feel the Story!", "color": "#F6D6D1", "ink": "#7A3A35", "teaser": "눈에 보이지 않아도 있는 것들", "qs": [{"type": "pickmany", "label": "모두 고르기", "q": "바람은 눈에 보이지 않아요. 그런데 바람이 불고 있다는 것을 어떻게 알 수 있을까요? 알맞은 그림을 모두 골라요.", "en": "We cannot see the wind. How can we tell it is blowing? Choose all the correct pictures.", "opts": [["흔들리는 나뭇잎", "Moving leaves", "leaf"], ["날아가는 연", "Flying kite", "kite"], ["움직이지 않는 돌", "Still rock", "rock"]], "answer": [0, 1], "ok": "맞아요! 흔들리는 나뭇잎과 날아가는 연을 보면 바람이 부는 것을 알 수 있어요.", "no": "다시 살펴봐요. 바람이 불면 무엇이 움직일까요?"}, {"type": "multi", "label": "모두 고르기", "q": "눈에 보이지 않아도 있다는 것을 알 수 있는 것들이 있어요. 알맞은 것을 모두 골라요.", "en": "Some things cannot be seen, but we can still know they are there. Choose all the correct answers.", "opts": [["사랑", "Love"], ["바람", "Wind"], ["소리", "Sound"], ["돌멩이", "Rock"]], "answer": [0, 1, 2], "ok": "잘했어요! 눈에 보이지 않아도 있는 것들이 있어요.", "no": "돌멩이는 눈으로 볼 수 있어요. 다시 골라 볼까요?"}, {"type": "multi", "free": true, "label": "모두 골라 보기", "q": "하나님은 눈에 보이지 않으세요. 여러분은 언제 하나님을 생각하나요? 해당하는 것을 모두 골라요.", "en": "We cannot see God. When do you think about Him? Check all that apply.", "opts": [["기도할 때", "When I pray"], ["찬양할 때", "When I sing praise"], ["성경을 읽을 때", "When I read the Bible"], ["어려운 일이 있을 때", "When things are hard"]], "answer": [0, 1, 2, 3], "ok": "좋아요! 하나님을 생각하는 때를 떠올려 봤어요."}, {"type": "text", "bubble": true, "label": "말풍선 쓰기", "q": "하나님이 계시다는 것을 믿는다면, 하나님께 어떤 말을 하고 싶나요? 말풍선에 적어 보세요.", "en": "If you believe God exists, what would you like to say to Him? Write it in the speech bubble.", "ph": "하나님께 하고 싶은 말", "ok": "멋져요! 하나님께 드리는 말이 곧 기도예요."}]}, "tue": {"name": "말씀 찾기", "tag": "VIEWING WHAT HAS BEEN GIVEN", "title": "말씀에 있는 그대로 찾아요", "en": "Explore the Word.", "color": "#E1DBF8", "ink": "#4F4290", "teaser": "믿음이 무엇인지 말씀에서 찾아요", "qs": [{"type": "blanks", "label": "빈칸 채우기 · 1절", "q": "히브리서 11장 1절을 읽고 빈칸을 채워 보세요.", "en": "Read Hebrews 11:1 and fill in the blanks.", "lines": [["믿음은 바라는 것들의 ", 0, "이요, 보이지 않는 것들의 ", 1, "니"]], "words": ["실상", "증거", "소원", "상상"], "answers": ["실상", "증거"], "ok": "맞아요! 믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거예요."}, {"type": "single", "label": "고르기 · 3절", "q": "하나님은 무엇으로 세상을 만드셨나요?", "en": "How did God create the universe?", "opts": [["사람의 힘으로", "By human strength"], ["하나님의 말씀으로", "By God’s word"], ["천사의 도움으로", "With the help of angels"], ["저절로 만들어졌어요.", "It came into being by itself."]], "answer": 1, "ok": "맞아요! 하나님은 말씀으로 세상을 만드셨어요.", "no": "3절을 다시 읽어 볼까요?"}, {"type": "match", "label": "짝 맞추기 · 4-5절", "q": "믿음의 사람들과 그들이 한 일을 연결해요. 왼쪽을 누르고 알맞은 말을 오른쪽에서 눌러요.", "en": "Match each person with what the Bible says. Tap a name on the left, then tap the matching sentence on the right.", "left": [["아벨", "Abel"], ["에녹", "Enoch"]], "right": [["하나님을 기쁘시게 했어요.", "Pleased God by faith."], ["믿음으로 제사를 드렸어요.", "Offered a sacrifice to God by faith."]], "answer": [1, 0], "ok": "모두 맞았어요! 아벨은 믿음으로 제사를 드렸고, 에녹은 하나님을 기쁘시게 했어요."}, {"type": "single", "label": "고르기 · 6절", "q": "하나님을 기쁘시게 하려면 무엇이 있어야 하나요?", "en": "What do we need to please God?", "opts": [["믿음", "Faith"], ["많은 돈", "Lots of money"], ["큰 힘", "Great strength"], ["많은 지식", "A lot of knowledge"]], "answer": 0, "ok": "맞아요! 믿음이 없이는 하나님을 기쁘시게 할 수 없어요.", "no": "6절을 다시 읽어 볼까요?"}]}, "wed": {"name": "숨은 이야기", "tag": "FINDING HIDDEN STORIES", "title": "숨은 마음을 발견해요!", "en": "Discover the Heart!", "color": "#DCE7C6", "ink": "#44572A", "teaser": "아벨과 에녹의 믿음 이야기", "qs": [{"type": "single", "label": "고르기 · 4절", "q": "아벨은 하나님께 믿음으로 제사를 드렸어요. 아벨의 마음을 가장 잘 나타내는 것은 무엇일까요?", "en": "Abel offered a sacrifice to God by faith. Which statement best shows Abel’s heart?", "opts": [["하나님을 믿고 예배드리고 싶어요.", "I want to trust and worship God."], ["다른 사람들에게 칭찬받고 싶어요.", "I want others to praise me."], ["유명해지고 싶어요.", "I want to be more famous than others."]], "answer": 0, "ok": "맞아요! 아벨은 하나님을 믿고 예배드리고 싶어 했어요.", "no": "4절을 다시 읽어 볼까요?"}, {"type": "ox", "label": "O / X · 창 5:24", "q": "에녹은 하나님과 동행했어요. 하나님과 동행한다는 것은 무엇을 의미할까요? 맞으면 O, 틀리면 X를 골라요.", "en": "Enoch walked with God. What does it mean to walk with God? Mark O for true or X for false.", "items": [["하나님을 믿고 의지하며 살아요.", "Live trusting and depending on God.", "O"], ["하나님의 말씀을 따라 살아요.", "Live according to God’s Word.", "O"], ["하나님을 잊고 내 마음대로 살아요.", "Forget God and live only my own way.", "X"]], "ok": "잘했어요! 하나님과 동행하는 것은 하나님을 믿고 의지하며 말씀대로 사는 거예요."}, {"type": "blanks", "label": "빈칸 채우기 · 4-6절", "q": "아벨과 에녹은 서로 다른 삶을 살았지만, 두 사람 모두 하나님을 믿었어요.", "en": "Abel and Enoch lived different lives, but both trusted God.", "lines": [["아벨과 에녹은 하나님을 ", 0, " 사람들이었어요."]], "words": ["믿었던", "잊어버린"], "answers": ["믿었던"], "ok": "맞아요! 아벨과 에녹은 하나님을 믿었던 사람들이에요."}, {"type": "single", "label": "고르기 · 4-6절", "q": "히브리서를 쓴 사람은 왜 아벨과 에녹의 믿음을 소개했을까요?", "en": "Why did the writer of Hebrews tell us about Abel and Enoch’s faith?", "opts": [["누가 더 훌륭한 사람인지 비교하려고", "To compare who was better."], ["아벨과 에녹처럼 유명해지라고", "To teach us to become famous like them."], ["우리가 하나님을 믿고 따르도록 격려하려고", "To encourage us to trust and follow God."]], "answer": 2, "ok": "맞아요! 우리도 하나님을 믿고 따르도록 격려하려고 소개했어요.", "no": "다시 생각해 봐요. 믿음의 사람들은 우리에게 어떤 도움을 줄까요?"}]}, "thu": {"name": "하나님 마음", "tag": "ENCOUNTERING THE HEART OF GOD", "title": "하나님의 마음을 알아가요!", "en": "Getting to Know God's Heart!", "color": "#FBE3D2", "ink": "#8A4A22", "teaser": "하나님은 어떤 사람을 기뻐하실까?", "qs": [{"type": "blanks", "label": "빈칸 채우기 · 6절", "q": "하나님께 나아가는 사람은 무엇을 믿어야 할까요?", "en": "What must we believe when we come to God?", "lines": [["① 하나님이 ", 0, " 것을 믿어요."], ["② 하나님이 자기를 찾는 사람들에게 ", 1, " 주시는 분임을 믿어요."]], "words": ["계시는", "상을", "떠나시는", "잊으시는"], "answers": ["계시는", "상을"], "ok": "잘했어요! 하나님은 계시고, 자기를 찾는 사람들에게 상을 주시는 분이에요."}, {"type": "single", "label": "고르기 · 6절", "q": "하나님은 어떤 사람을 기뻐하실까요?", "en": "Who pleases God?", "opts": [["실수하지 않는 사람", "Someone who never makes mistakes."], ["하나님을 믿고 찾는 사람", "Someone who trusts and seeks God."], ["모든 일을 잘하는 사람", "Someone who does everything perfectly."]], "answer": 1, "ok": "맞아요! 하나님은 하나님을 믿고 찾는 사람을 기뻐하세요.", "no": "6절을 다시 읽어 볼까요?"}, {"type": "fill", "label": "써 보기 · 5절 · 12:2", "q": "에녹의 믿음과 예수님이 하시는 일을 비교해 보세요. 성경에서 찾아 빈칸에 적어 보세요.", "en": "Compare Enoch’s faith with Jesus’ work. Find the words in the Bible and write them in the blanks.", "parts": ["① 에녹 (히브리서 11:5)<br>“그는 하나님을 기쁘시게 하는 자라 하는 ", 0, "를 받았느니라”<br>② 예수님 (히브리서 12:2)<br>“믿음의 주요 또 온전하게 하시는 이인 ", 1, "를 바라보자”"], "ok": "잘 찾았어요! 에녹은 하나님을 기쁘시게 했고, 예수님은 우리 믿음을 온전하게 하세요."}, {"type": "single", "label": "고르기 · 12:2", "q": "에녹은 믿음으로 하나님을 기쁘시게 했어요. 우리는 누구를 바라보며 믿음으로 살아가야 할까요?", "en": "Enoch pleased God by faith. Who should we look to as we live by faith?", "opts": [["나 자신", "Myself"], ["유명한 사람들", "Famous people"], ["예수님", "Jesus"]], "answer": 2, "ok": "맞아요! 우리는 믿음의 주이신 예수님을 바라봐요.", "no": "히브리서 12:2를 다시 읽어 볼까요?"}]}, "fri": {"name": "내 삶으로", "tag": "INTO MY LIFE", "title": "나는 어떻게 살아야 할까요?", "en": "How Should I Live?", "color": "#FBEBB8", "ink": "#6E5410", "teaser": "걱정될 때 어떻게 할까?", "qs": [{"type": "match", "label": "짝 맞추기 · 1, 6절", "q": "내가 원하는 대로 되지 않을 때도 있어요. 하나님을 믿는 사람은 어떻게 행동할 수 있을까요? 왼쪽 상황을 누르고 알맞은 행동을 오른쪽에서 눌러요.", "en": "Sometimes things don’t go the way we want. What can we do when we trust God? Tap a situation on the left, then tap the matching action of faith.", "left": [["열심히 공부했지만 시험이 걱정돼요.", "I studied hard, but I’m worried about my test."], ["기도했지만 아직 원하는 일이 이루어지지 않았어요.", "I prayed, but what I hoped for hasn’t happened yet."], ["친구와 화해하고 싶지만 용기가 나지 않아요.", "I want to make peace with my friend, but I’m afraid."]], "right": [["하나님을 믿고 기다리며 계속 기도해요.", "Trust God, wait, and keep praying."], ["하나님께 도움을 구하고 먼저 다가가요.", "Ask God for help and reach out first."], ["결과를 하나님께 맡기고 최선을 다해요.", "Trust God with the result and do my best."]], "answer": [2, 0, 1], "ok": "모두 맞았어요! 걱정될 때도 하나님을 믿고 의지할 수 있어요."}, {"type": "multi", "free": true, "label": "실천하고 싶은 것 고르기 · 12:2", "q": "어려운 일이 있을 때, 어떻게 예수님을 바라볼 수 있을까요? 실천하고 싶은 행동을 모두 골라요.", "en": "How can you look to Jesus when things are hard? Check the actions you want to practice.", "opts": [["예수님께 걱정을 말씀드려요.", "Tell Jesus my worries."], ["예수님의 말씀을 따라요.", "Follow Jesus’ words."], ["예수님께 도움을 구해요.", "Ask Jesus for help."], ["예수님이 함께하심을 믿어요.", "Trust that Jesus is with me."]], "answer": [0, 1, 2, 3], "ok": "좋아요! 예수님을 바라보는 방법을 골랐어요."}, {"type": "fill", "label": "기도 완성하기", "q": "요즘 걱정하거나 기다리고 있는 일이 있나요? 한 가지를 적고 기도를 완성해 봐요.", "en": "Is there something you are worried about or waiting for? Write it down and complete the prayer.", "parts": ["하나님, 저는 지금 ", 0, " 때문에 걱정이 돼요(기다리고 있어요).<br>그래도 하나님을 믿고 ", 1, " 하게 도와주세요."], "ok": "기도해 줘서 고마워요! 하나님은 우리의 마음을 들어 주세요."}]}};
var LESSONS33_EN={"mon": {"name": "Open Hearts", "title": "Feel the Story!", "teaser": "Things we cannot see, but know are real", "qs": [{"label": "Choose all", "q": "We cannot see the wind. How can we tell it is blowing? Choose all the correct pictures.", "ok": "That’s right! Moving leaves and a flying kite show us the wind is blowing.", "no": "Let’s look again. What moves when the wind blows?"}, {"label": "Choose all", "q": "Some things cannot be seen, but we can still know they are there. Choose all the correct answers.", "ok": "Well done! Some things cannot be seen, but they are real.", "no": "We can see a rock with our eyes. Let’s choose again."}, {"label": "Check all that apply", "q": "We cannot see God. When do you think about Him? Check all that apply.", "ok": "Good! You thought about when you think of God."}, {"label": "Speech bubble", "q": "If you believe God exists, what would you like to say to Him? Write it in the speech bubble.", "ok": "Wonderful! Words to God are prayer.", "ph": "What I want to say to God"}]}, "tue": {"name": "Find the Word", "title": "Explore the Word", "teaser": "Find out what faith is in the Bible", "qs": [{"label": "Fill in the blanks · v. 1", "q": "Read Hebrews 11:1 and fill in the blanks.", "ok": "That’s right! Faith is the assurance of things hoped for, the conviction of things not seen.", "lines": [["Faith is the ", 0, " of things hoped for, the ", 1, " of things not seen."]], "wordsEn": ["assurance", "conviction", "wish", "imagination"]}, {"label": "Choose · v. 3", "q": "How did God create the universe?", "ok": "That’s right! God created the universe by His word.", "no": "Let’s read verse 3 again."}, {"label": "Match · vv. 4–5", "q": "Match each person with what the Bible says. Tap a name on the left, then tap the matching sentence on the right.", "ok": "All correct! Abel offered a sacrifice by faith, and Enoch pleased God."}, {"label": "Choose · v. 6", "q": "What do we need to please God?", "ok": "That’s right! Without faith it is impossible to please God.", "no": "Let’s read verse 6 again."}]}, "wed": {"name": "Hidden Story", "title": "Discover the Heart!", "teaser": "The faith of Abel and Enoch", "qs": [{"label": "Choose · v. 4", "q": "Abel offered a sacrifice to God by faith. Which statement best shows Abel’s heart?", "ok": "That’s right! Abel wanted to trust and worship God.", "no": "Let’s read verse 4 again."}, {"label": "True or False · Gen 5:24", "q": "Enoch walked with God. What does it mean to walk with God? Mark O for true or X for false.", "ok": "Well done! Walking with God means trusting Him and following His Word."}, {"label": "Fill in the blank · vv. 4–6", "q": "Abel and Enoch lived different lives, but both trusted God.", "ok": "That’s right! Abel and Enoch were people who trusted God.", "lines": [["Abel and Enoch were people who ", 0, " God."]], "wordsEn": ["trusted", "forgot"]}, {"label": "Choose · vv. 4–6", "q": "Why did the writer of Hebrews tell us about Abel and Enoch’s faith?", "ok": "That’s right! He wanted to encourage us to trust and follow God.", "no": "Let’s think again. How can people of faith help us?"}]}, "thu": {"name": "God's Heart", "title": "Getting to Know God's Heart!", "teaser": "Who pleases God?", "qs": [{"label": "Fill in the blanks · v. 6", "q": "What must we believe when we come to God?", "ok": "Well done! God exists, and He rewards those who seek Him.", "lines": [["① Believe that God ", 0, "."], ["② Believe that God ", 1, " those who seek Him."]], "wordsEn": ["exists", "rewards", "leaves", "forgets"]}, {"label": "Choose · v. 6", "q": "Who pleases God?", "ok": "That’s right! God is pleased with someone who trusts and seeks Him.", "no": "Let’s read verse 6 again."}, {"label": "Write · v. 5 · 12:2", "q": "Compare Enoch’s faith with Jesus’ work. Find the words in the Bible and write them in the blanks.", "ok": "Great finding! Enoch pleased God, and Jesus perfects our faith.", "parts": ["① Enoch (Hebrews 11:5)<br>“He was commended as having ", 0, " God.”<br>② Jesus (Hebrews 12:2)<br>“Looking to ", 1, ", the founder and perfecter of our faith.”"]}, {"label": "Choose · 12:2", "q": "Enoch pleased God by faith. Who should we look to as we live by faith?", "ok": "That’s right! We look to Jesus, the founder of our faith.", "no": "Let’s read Hebrews 12:2 again."}]}, "fri": {"name": "Into My Life", "title": "How Should I Live?", "teaser": "What can I do when I am worried?", "qs": [{"label": "Match · vv. 1, 6", "q": "Sometimes things don’t go the way we want. What can we do when we trust God? Tap a situation on the left, then tap the matching action of faith.", "ok": "All correct! Even when we are worried, we can trust God."}, {"label": "Choose the ones you want to do · 12:2", "q": "How can you look to Jesus when things are hard? Check the actions you want to practice.", "ok": "Good! You chose ways to look to Jesus."}, {"label": "Finish the prayer", "q": "Is there something you are worried about or waiting for? Write it down and complete the prayer.", "ok": "Thank you for praying! God listens to our hearts.", "parts": ["Dear God, I am worried about (or waiting for) ", 0, ".<br>Help me trust You and ", 1, ". Amen."]}]}};
/* parent guide #33 (text from the church's guide, Korean and English) */
var PG33={"week": {"chip": "이번 주 말씀 한눈에 보기", "title": "믿음으로 살아가요!", "sub": "히브리서 — 보이지 않는 하나님을 신뢰하는 믿음", "period": "2026.11.2–11.8 · 부모님을 위한 묵상 가이드", "ref": "히브리서 11:1-6", "color": "#FBEBB8", "ink": "#6E5410", "desc": "한 주의 핵심 메시지와 주제", "refs": [["본문", "히브리서 11:1–6"], ["참고 말씀", "히브리서 11장, 12:1–2"], ["암송 말씀", "히브리서 11:6"]], "parts": [["보이지 않는 하나님을 신뢰하는 믿음", ["히브리서는 신앙 때문에 어려움을 겪고 있던 성도들에게 믿음을 굳게 지키도록 권면하는 말씀입니다. 그들은 예수님을 믿는다는 이유로 여러 어려움을 경험했고, 신앙을 포기하고 싶은 유혹과도 마주해야 했습니다.", "이러한 성도들에게 히브리서 기자는 믿음으로 살아갔던 구약의 사람들을 소개합니다. 그들은 모두 서로 다른 시대와 환경 속에서 살았지만, 눈에 보이는 상황보다 하나님과 그분의 약속을 신뢰하며 살아갔습니다.", "히브리서 11장 1절은 믿음을 '바라는 것들의 실상이요 보이지 않는 것들의 증거'라고 설명합니다. 여기에서 믿음은 단순히 눈에 보이지 않는 것을 사실이라고 생각하거나, 간절히 바라는 일이 반드시 이루어질 것이라고 확신하는 것이 아닙니다. 아직 눈앞에 결과가 나타나지 않았더라도 하나님이 신실하신 분임을 믿고 의지하는 것입니다.", "이번 주 본문은 아벨과 에녹이라는 두 사람을 소개합니다.", "아벨은 믿음으로 하나님께 더 나은 제사를 드렸고, 에녹은 하나님과 동행하며 하나님을 기쁘시게 한 사람으로 인정받았습니다. 두 사람의 삶은 서로 달랐지만, 그들이 하나님께 나아가는 중심에는 믿음이 있었습니다.", "히브리서 11장 6절은 믿음이 없이는 하나님을 기쁘시게 할 수 없다고 말씀합니다. 하나님께 나아가는 사람은 하나님이 계신 것과 자신을 찾는 사람들에게 상 주시는 분임을 믿어야 합니다.", "여기에서 '상'은 우리가 하나님께 기도하거나 순종하면 원하는 것을 반드시 얻게 된다는 의미가 아닙니다. 하나님은 자신을 찾는 사람들을 외면하지 않으시며, 자신의 약속에 신실하신 분이라는 사실을 보여 줍니다.", "히브리서 11장의 마지막은 믿음의 사람들조차 하나님의 약속이 완전히 이루어지는 것을 모두 보지는 못했다고 말씀합니다(11:39–40). 그리고 12장 2절에서는 우리의 시선을 예수님께로 향하게 합니다.", "예수님은 단순히 믿음의 좋은 본보기가 아니라 우리 믿음의 근원이시며 그 믿음을 온전하게 하시는 분입니다.", "이번 주 아이들이 배워야 할 믿음도 여기에 있습니다. 하나님을 믿는다고 해서 어려움이 없어지거나 원하는 일이 모두 이루어지는 것은 아닙니다. 그러나 어려움 가운데서도 예수님을 바라보고, 하나님께 도움을 구하며, 말씀을 따라 살아갈 수 있습니다."]]], "threeTitle": "이번 주 묵상의 세 가지 목표", "three": ["하나님은 눈에 보이지 않지만 살아 계시며 신뢰할 수 있는 분임을 알아갑니다.", "아벨과 에녹의 삶을 통해 믿음이 예배와 하나님과의 동행으로 나타난다는 사실을 배웁니다.", "어려움과 기다림 속에서도 우리의 믿음을 온전하게 하시는 예수님을 바라보며 살아가는 방법을 익힙니다."], "verse": ["히브리서 11:6", "믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라"], "closing": {"title": "이번 주 부모님께 전하고 싶은 마지막 메시지", "body": ["이번 히브리서 묵상에서 가장 강조하고 싶은 것은 아이들이 믿음을 잘해야 하는 또 하나의 숙제로 여기지 않도록 하는 것입니다.", "아벨과 에녹의 삶을 배웠다고 해서 아이들에게 언제나 믿음이 좋아야 하고, 두려워하지 않아야 하며, 하나님을 실망시키지 않아야 한다는 부담을 주어서는 안 됩니다.", "히브리서는 믿음의 사람들을 소개한 후 우리의 시선을 예수님께로 돌립니다.", "아이들이 이번 주를 마칠 때 다음과 같은 고백을 할 수 있다면 좋겠습니다."], "ask": "“하나님, 저는 아직 하나님을 잘 모르는 것도 있고, 걱정되는 일도 있어요. 그래도 예수님을 바라보며 하나님을 믿고 살아가고 싶어요.”", "after": ["그렇게 믿음은 완벽한 사람에게 요구되는 조건이 아니라, 연약한 우리를 붙드시는 예수님을 신뢰하며 자라 가는 삶이라는 사실을 배워 가게 될 것입니다."]}}, "mon": {"day": "월요일", "name": "마음 열기", "sub": "말씀을 느껴요!", "title": "보이지 않는 것을 생각하며 믿음에 마음을 열어요.", "color": "#F6D6D1", "ink": "#7A3A35", "focus": "월요일에는 아이들이 바람을 관찰하는 것에서 출발합니다.", "body": ["바람 자체는 눈으로 볼 수 없지만, 흔들리는 나뭇잎이나 날아가는 연을 통해 바람이 불고 있다는 사실을 알 수 있습니다. 이어서 사랑과 소리처럼 눈에 보이지 않아도 존재를 알 수 있는 것들을 생각해 봅니다.", "이 활동의 목적은 자연현상을 통해 하나님의 존재를 증명하는 것이 아닙니다. 아이들이 <b>'눈에 보이지 않는다고 해서 존재하지 않는 것은 아니다'</b>라는 개념을 친숙한 경험으로 이해하도록 돕는 것입니다.", "이후 하나님을 언제 생각하는지 돌아보고, 하나님께 하고 싶은 말을 적도록 안내합니다.", "부모님께서는 아이가 하나님에 대해 어떤 생각을 가지고 있는지 먼저 들어 주세요. 아이가 기도하거나 찬양할 때 하나님을 생각한다고 답할 수도 있지만, 잘 모르겠다고 말할 수도 있습니다.", "믿음에 관한 질문에 반드시 긍정적인 답을 해야 한다는 부담을 주지 않는 것이 중요합니다. 오히려 자신의 생각과 궁금증을 솔직하게 표현하도록 격려해 주세요."], "tip": "\"우리는 하나님을 눈으로 볼 수 없지만, 성경을 통해 하나님이 어떤 분이신지 알아갈 수 있어. 하나님에 대해 궁금한 것이 있니?\""}, "tue": {"day": "화요일", "name": "말씀 찾기", "sub": "말씀에 있는 그대로 찾아요", "title": "성경이 말씀하는 믿음의 의미와 믿음의 사람들을 발견해요.", "color": "#E1DBF8", "ink": "#4F4290", "focus": "화요일에는 히브리서 11장 1–6절을 직접 읽고 믿음에 관해 성경이 무엇이라고 말씀하는지 찾아봅니다.", "body": ["첫 번째 질문에서는 '실상'과 '증거'라는 단어를 발견합니다. 이 단어들은 초등학교 저학년 아이들에게 어렵게 느껴질 수 있습니다.", "부모님께서는 '실상'을 하나님이 약속하신 것을 확신하는 마음으로, '증거'를 아직 눈으로 보지 못하더라도 하나님의 말씀을 신뢰하는 것으로 쉽게 설명해 주시면 좋겠습니다.", "3절에서는 하나님이 말씀으로 세상을 창조하셨다는 사실을 발견하고, 4–5절에서는 아벨과 에녹이라는 두 믿음의 사람을 만납니다.", "아벨은 믿음으로 제사를 드렸고 에녹은 하나님을 기쁘시게 했습니다. 여기에서 아이들이 발견해야 할 것은 단순히 두 사람의 이름과 행동을 연결하는 것이 아닙니다. 하나님을 기쁘시게 하는 삶에는 하나님을 향한 믿음이 있다는 사실입니다.", "특히 믿음이 어떤 특별한 능력이나 대단한 일을 이루는 힘이라고 이해하지 않도록 주의해 주세요."], "tip": "\"아벨과 에녹은 서로 다른 일을 했지만 둘 다 하나님을 믿었어. 하나님께서는 그들의 믿음을 기쁘게 보셨단다.\""}, "wed": {"day": "수요일", "name": "숨은 이야기", "sub": "숨은 마음을 발견해요!", "title": "아벨과 에녹의 행동에 담긴 믿음의 의미를 발견해요.", "color": "#DCE7C6", "ink": "#44572A", "focus": "수요일에는 본문에 기록된 행동을 한 걸음 더 깊이 살펴봅니다.", "body": ["아벨은 제사를 드렸습니다. 그러나 성경은 단순히 제사를 드렸다는 사실만을 강조하지 않고 '믿음으로' 더 나은 제사를 드렸다고 말씀합니다.", "창세기 4장의 이야기에서도 하나님은 아벨과 그의 제물을 받으셨다고 기록합니다. 따라서 부모님께서는 제물의 종류나 외적인 모습만으로 두 사람의 차이를 설명하기보다, 히브리서가 강조하는 하나님을 향한 믿음에 주목하도록 도와주세요.", "에녹에 관해서는 창세기 5장 22–24절이 하나님과 동행한 사람이라고 설명합니다. 하나님과 동행한다는 것은 하나님과 실제로 나란히 걸어 다녔다는 뜻이 아니라, 하나님과 지속적인 관계를 맺으며 그분을 의지하는 삶을 가리킵니다.", "아이들은 기도하거나 하나님의 말씀을 따르는 행동을 통해 그 의미를 이해할 수 있습니다.", "마지막 질문에서는 히브리서 기자가 왜 두 사람의 믿음을 소개했는지 생각합니다. 당시 어려움을 겪던 성도들에게 믿음으로 살아가는 모습을 보여 주고, 그들도 하나님을 계속 신뢰하도록 격려하기 위해서입니다."], "tip": "\"아벨은 하나님께 예배드렸고 에녹은 하나님과 동행했어. 하나님을 믿는 모습은 서로 달라도 괜찮아. 우리도 매일의 생활에서 하나님을 믿고 따를 수 있단다.\""}, "thu": {"day": "목요일", "name": "하나님 마음", "sub": "하나님의 마음을 알아가요!", "title": "믿음을 기뻐하시는 하나님과 믿음을 온전하게 하시는 예수님을 알아가요.", "color": "#FBE3D2", "ink": "#8A4A22", "focus": "목요일은 이번 주 묵상에서 가장 중요한 신학적 연결이 이루어지는 날입니다.", "body": ["먼저 히브리서 11장 6절을 통해 하나님이 계신 것과 자신을 찾는 사람들에게 상 주시는 분임을 배웁니다.", "'상을 주시는 하나님'이라는 표현을 설명할 때에는 특별한 주의가 필요합니다. 아이들은 하나님을 믿고 기도하면 좋은 성적을 받거나 원하는 선물을 얻게 된다고 이해할 수 있습니다.", "그러나 하나님을 믿는 것은 원하는 결과를 얻기 위한 방법이 아닙니다. 하나님이 자신을 찾는 사람들을 외면하지 않으시며 약속에 신실하신 분이라는 사실을 신뢰하는 것입니다.", "이후 히브리서 12장 2절을 통해 우리의 시선이 예수님께로 향하게 됩니다.", "아벨과 에녹은 믿음으로 하나님을 기쁘시게 한 사람들이지만, 예수님은 우리의 믿음을 시작하시고 온전하게 하시는 분입니다.", "아이들이 예수님을 바라본다는 말을 실제로 예수님의 모습을 눈으로 찾는 일로 이해하지 않도록 도와주세요. 예수님을 바라본다는 것은 예수님이 누구신지 기억하고, 그분의 말씀을 신뢰하며, 그분께 도움을 구하고 의지하는 것을 의미합니다."], "tip": "\"하나님은 우리가 하나님을 믿고 찾아오는 것을 기뻐하셔. 그리고 예수님은 우리의 믿음을 도와주시고 온전하게 하시는 분이야. 그러니까 믿음이 약해질 때에도 예수님께 나아갈 수 있어.\""}, "fri": {"day": "금요일", "name": "내 삶으로", "sub": "나는 어떻게 살아야 할까요?", "title": "어려움과 기다림 속에서도 예수님을 바라보며 믿음으로 살아가요.", "color": "#D6ECF5", "ink": "#2F5A72", "focus": "금요일에는 한 주 동안 배운 믿음의 의미를 아이들의 실제 생활에 적용합니다.", "body": ["시험이 걱정되거나, 기도한 일이 아직 이루어지지 않았거나, 친구에게 먼저 다가갈 용기가 나지 않는 상황을 생각합니다.", "이러한 질문의 목적은 아이들에게 무조건 긍정적으로 생각하거나 두려움을 없애라고 가르치는 것이 아닙니다.", "믿음은 걱정이 없는 상태가 아니라 걱정되는 상황에서도 하나님께 나아가고 그분을 의지하는 것임을 배우도록 돕는 것입니다.", "예를 들어 시험이 걱정될 때에는 기도하며 최선을 다해 준비할 수 있습니다. 기도한 일이 아직 이루어지지 않았다면 하나님께 자신의 마음을 계속 말씀드리며 기다릴 수 있습니다. 친구와 화해하는 일이 두렵다면 예수님께 도움을 구하고 용기를 내어 먼저 다가갈 수 있습니다.", "두 번째 질문에서는 예수님을 바라보는 구체적인 행동을 선택합니다. 기도하고, 예수님의 말씀을 따르며, 도움을 구하고, 예수님이 함께하심을 믿는 일은 믿음이 일상에서 나타나는 실제적인 모습입니다.", "마지막 질문에서는 자신의 걱정이나 기다림을 직접 기도로 표현합니다.", "부모님께서는 아이가 적은 걱정을 가볍게 여기지 말고 함께 들어 주세요. 아이가 기다리는 일이 이루어질 것이라고 쉽게 약속하기보다는, 결과를 알 수 없는 상황에서도 하나님께 마음을 맡길 수 있도록 격려하는 것이 중요합니다."], "tip": "\"하나님을 믿는다고 해서 모든 일이 우리 마음대로 되는 것은 아니야. 하지만 어떤 일이 생겨도 우리는 하나님께 기도할 수 있어. 예수님을 바라보며 함께 믿음으로 걸어가 보자.\""}};
var PG33_EN={"week": {"chip": "This Week at a Glance", "title": "Live by Faith!", "sub": "Hebrews — Trusting the God We Cannot See", "period": "Nov 2 – Nov 8, 2026 · Devotional Guide for Parents", "ref": "Hebrews 11:1–6", "desc": "This week’s main message and theme", "refs": [["Passage", "Hebrews 11:1–6"], ["Further reading", "Hebrews 11; 12:1–2"], ["Memory verse", "Hebrews 11:6"]], "parts": [["Trusting the God We Cannot See", ["The book of Hebrews encourages believers who were facing difficulties because of their faith to remain steadfast in trusting God. They experienced hardship and faced the temptation to turn away from what they believed.", "To encourage them, the writer of Hebrews introduces people from the Old Testament who lived by faith. Although they lived in different times and circumstances, they shared something important: they trusted God and His promises even when they could not see how everything would turn out.", "Hebrews 11:1 describes faith as the assurance of things hoped for and the conviction of things not seen.", "Faith does not simply mean believing that something invisible exists. Nor does it mean being certain that everything we wish for will happen. Faith means trusting that God is faithful, even when we cannot yet see the outcome.", "This week's passage introduces two people of faith: Abel and Enoch.", "Abel offered a better sacrifice to God by faith, and Enoch was commended as someone who pleased God. Although their lives were different, both demonstrated faith in God.", "Hebrews 11:6 teaches that without faith it is impossible to please God. Those who come to Him must believe that He exists and that He rewards those who seek Him.", "The promise that God rewards those who seek Him should not be understood as a guarantee that He will give us everything we ask for. Rather, it reminds us that God is faithful and does not disregard those who seek Him.", "Toward the end of Hebrews 11, we learn that even the great examples of faith did not receive the complete fulfillment of everything God had promised during their lifetimes (Hebrews 11:39–40). The writer then directs our attention to Jesus in Hebrews 12:2.", "Jesus is not simply another example of faith. He is the founder and perfecter of our faith.", "Through this week's devotional, children will discover that trusting God does not mean life will always be easy. Even when they are worried, afraid, or waiting for an answer, they can look to Jesus and continue trusting God."]]], "threeTitle": "Three Goals for This Week", "three": ["Discover that God exists, even though we cannot see Him, and that He is worthy of our trust.", "Learn through Abel and Enoch that faith is expressed through worship and walking with God.", "Practice looking to Jesus, the founder and perfecter of our faith, in everyday situations."], "verse": ["Hebrews 11:6", "And without faith it is impossible to please him, for whoever would draw near to God must believe that he exists and that he rewards those who seek him."], "closing": {"title": "A Final Message for Parents This Week", "body": ["The most important thing we hope for in this study of Hebrews is that children do not treat faith as one more assignment to do well.", "Having learned about Abel and Enoch, children should not feel pressure to always have strong faith, never be afraid, or never disappoint God.", "After introducing the people of faith, Hebrews turns our eyes to Jesus.", "We hope that at the end of this week your child can say something like this:"], "ask": "“God, there are still things I don’t know about You, and there are things I am worried about. Even so, I want to look to Jesus and live trusting You.”", "after": ["Faith is not about being perfect. It is about learning to trust Jesus, who holds us and brings our faith to completion."]}}, "mon": {"day": "Monday", "name": "Open Hearts", "sub": "Feel the Story!", "title": "Exploring what we cannot see and opening our hearts to faith.", "focus": "Monday begins with a familiar experience: the wind.", "body": ["Although children cannot see the wind itself, they can recognize its presence through moving leaves or a flying kite. They then consider other things, such as love and sound, that cannot be seen but whose presence can still be recognized.", "The purpose of this activity is not to prove God's existence through natural examples. Rather, it helps children understand that something does not have to be visible to be real.", "Children then think about when they remember God and what they would like to say to Him.", "Encourage your child to express their thoughts freely. Some children may confidently describe their faith, while others may have questions or uncertainties.", "Avoid pressuring children to give what they think is the correct answer. Their honest thoughts can become a meaningful starting point for conversations about God."], "tip": "\"We cannot see God with our eyes, but we can learn about Him through the Bible. Is there anything you wonder about God?\""}, "tue": {"day": "Tuesday", "name": "Find the Word", "sub": "Explore the Word.", "title": "Discovering what the Bible teaches about faith.", "focus": "On Tuesday, children read Hebrews 11:1–6 and identify what Scripture teaches about faith.", "body": ["The words assurance and conviction may be difficult for younger children. Explain assurance as confidence in what God has promised and conviction as trusting God's Word even when we cannot see everything He is doing.", "Verse 3 teaches that God created the universe by His word. Verses 4–5 introduce Abel and Enoch as examples of faith.", "Abel offered a sacrifice by faith, and Enoch was commended for pleasing God.", "Help your child notice that the central lesson is not simply what these people accomplished, but their trust in God.", "Faith is not a special power that enables us to achieve extraordinary things. It is trusting the God who is faithful."], "tip": "\"Abel and Enoch did different things, but they both trusted God. God was pleased with their faith.\""}, "wed": {"day": "Wednesday", "name": "Hidden Story", "sub": "Discover the Heart!", "title": "Discovering the faith behind Abel's and Enoch's actions.", "focus": "Wednesday helps children move beyond identifying what Abel and Enoch did to considering the faith behind their actions.", "body": ["Hebrews emphasizes that Abel offered a better sacrifice by faith. Genesis 4 also describes how God regarded Abel and his offering.", "Rather than focusing only on the type or appearance of the sacrifice, guide your child to notice the importance Hebrews places on Abel's faith.", "Genesis 5:22–24 tells us that Enoch walked with God. This does not mean that he was simply walking physically beside God. It describes a life of ongoing fellowship with and trust in God.", "Children can begin to understand this through familiar practices such as prayer, listening to God's Word, and choosing to follow Him.", "The final question invites children to consider why the writer of Hebrews included these examples. The writer wanted to encourage believers facing difficulties to continue trusting God."], "tip": "\"Abel worshiped God, and Enoch walked with God. Their lives were different, but both trusted Him. We can also trust and follow God in our everyday lives.\""}, "thu": {"day": "Thursday", "name": "God's Heart", "sub": "Getting to Know God's Heart!", "title": "Knowing the God who is pleased by faith and Jesus who perfects our faith.", "focus": "Thursday brings together two important truths from Hebrews 11:6 and 12:2.", "body": ["First, children learn that those who come to God must believe He exists and that He rewards those who seek Him.", "Be careful when explaining God's reward. Children may assume that praying or obeying God guarantees good grades, special gifts, or the answers they want.", "Help them understand that faith is not a way to obtain everything we desire. God is faithful, and He does not disregard those who seek Him.", "Next, children discover Jesus as the founder and perfecter of our faith.", "Abel and Enoch are examples of people who trusted God, but Jesus is more than an example. He is the One through whom our faith begins and is brought to completion.", "Explain that looking to Jesus does not mean trying to see Him with our physical eyes. It means remembering who He is, trusting His Word, seeking His help, and depending on Him."], "tip": "\"God is pleased when we trust and seek Him. Jesus is the One who helps us grow in faith. Even when our faith feels weak, we can come to Him.\""}, "fri": {"day": "Friday", "name": "Into My Life", "sub": "How Should I Live?", "title": "Looking to Jesus and practicing faith in everyday life.", "focus": "Friday invites children to apply what they have learned to real situations.", "body": ["They consider what to do when they are worried about a test, when a prayer has not yet been answered, or when they are afraid to approach a friend after an argument.", "The goal is not to teach children that faith means having no fear or always thinking positively.", "Faith does not mean the absence of worry. It means learning to trust God even when we are worried.", "A child who is anxious about a test can pray and prepare responsibly. A child waiting for an answer to prayer can continue bringing that hope to God. A child who is afraid to make peace with a friend can ask Jesus for help and take a courageous step.", "The second question invites children to identify practical ways to look to Jesus: praying honestly, following His Word, asking for help, and remembering His presence.", "The final activity encourages children to express their own worries or hopes through prayer.", "Listen carefully to what your child shares. Avoid making promises that a particular outcome will happen. Instead, reassure them that they can bring their concerns to God and continue trusting Him."], "tip": "\"Trusting God does not mean everything will happen exactly the way we want. But whatever happens, we can pray, seek His help, and keep looking to Jesus.\""}};
var BOOK33={id:'heb-11-1-6',no:33,ch:11,book:['히브리서','Hebrews'],title:'믿음으로 살아가요!',ref:'히브리서 11:1-6',verses:VERSES33,art:'cuteKite'};
var MEM33={"id": "heb-11-6", "vi": 5, "ko": ["믿음이 없이는", "하나님을 기쁘시게 하지 못하나니", "하나님께 나아가는 자는", "반드시 그가 계신 것과", "또한 그가 자기를 찾는 자들에게", "상 주시는 이심을", "믿어야 할지니라"], "en": ["And without faith it is impossible to please him,", "for whoever would draw near to God", "must believe that he exists", "and that he rewards those who seek him."]};
var PACK33={no:33,start:new Date(2026,10,2),code:'heb',
 title:'믿음으로 살아가요!',titleEn:'Live by Faith!',
 ref:'히브리서 11:1-6',refEn:'Hebrews 11:1–6',
 memRef:'히브리서 11:6',memRefEn:'Hebrews 11:6',
 mem:'믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라',memEn:'And without faith it is impossible to please him, for whoever would draw near to God must believe that he exists and that he rewards those who seek him.',
 verses:VERSES33,lessons:LESSONS33,lessonsEn:LESSONS33_EN,pg:PG33,pgEn:PG33_EN,book:BOOK33,memo:MEM33,bible:BIBLE33};

/* ---------- #34 · 야고보서 2:21-26 · 믿음은 행동으로 보여요 (2026.11.9–11.15) ---------- */
var VERSES34=[[21, "우리 조상 아브라함이 그 아들 이삭을 제단에 바칠 때에 행함으로 의롭다 하심을 받은 것이 아니냐", "Was not Abraham our father justified by works when he offered up his son Isaac on the altar?"], [22, "네가 보거니와 믿음이 그의 행함과 함께 일하고 행함으로 믿음이 온전하게 되었느니라", "You see that faith was active along with his works, and faith was completed by his works;"], [23, "이에 성경에 이른 바 아브라함이 하나님을 믿으니 이것을 의로 여기셨다는 말씀이 이루어졌고 그는 하나님의 벗이라 칭함을 받았나니", "and the Scripture was fulfilled that says, “Abraham believed God, and it was counted to him as righteousness”—and he was called a friend of God."], [24, "이로 보건대 사람이 행함으로 의롭다 하심을 받고 믿음으로만은 아니니라", "You see that a person is justified by works and not by faith alone."], [25, "또 이와 같이 기생 라합이 사자들을 접대하여 다른 길로 나가게 할 때에 행함으로 의롭다 하심을 받은 것이 아니냐", "And in the same way was not also Rahab the prostitute justified by works when she received the messengers and sent them out by another way?"], [26, "영혼 없는 몸이 죽은 것 같이 행함이 없는 믿음은 죽은 것이니라", "For as the body apart from the spirit is dead, so also faith apart from works is dead.", 1]];
var BIBLE34={"jas": {"2": {"1": ["내 형제들아 영광의 주 곧 우리 주 예수 그리스도에 대한 믿음을 너희가 가졌으니 사람을 차별하여 대하지 말라", "My brothers, show no partiality as you hold the faith in our Lord Jesus Christ, the Lord of glory."], "2": ["만일 너희 회당에 금 가락지를 끼고 아름다운 옷을 입은 사람이 들어오고 또 남루한 옷을 입은 가난한 사람이 들어올 때에", "For if a man wearing a gold ring and fine clothing comes into your assembly, and a poor man in shabby clothing also comes in,"], "3": ["너희가 아름다운 옷을 입은 자를 눈여겨 보고 말하되 여기 좋은 자리에 앉으소서 하고 또 가난한 자에게 말하되 너는 거기 서 있든지 내 발등상 아래에 앉으라 하면", "and if you pay attention to the one who wears the fine clothing and say, “You sit here in a good place,” while you say to the poor man, “You stand over there,” or, “Sit down at my feet,”"], "4": ["너희끼리 서로 차별하며 악한 생각으로 판단하는 자가 되는 것이 아니냐", "have you not then made distinctions among yourselves and become judges with evil thoughts?"], "5": ["내 사랑하는 형제들아 들을지어다 하나님이 세상에서 가난한 자를 택하사 믿음에 부요하게 하시고 또 자기를 사랑하는 자들에게 약속하신 나라를 상속으로 받게 하지 아니하셨느냐", "Listen, my beloved brothers, has not God chosen those who are poor in the world to be rich in faith and heirs of the kingdom, which he has promised to those who love him?"]}}, "gen": {"22": {"1": ["그 일 후에 하나님이 아브라함을 시험하시려고 그를 부르시되 아브라함아 하시니 그가 이르되 내가 여기 있나이다", "After these things God tested Abraham and said to him, “Abraham!” And he said, “Here I am.”"], "2": ["여호와께서 이르시되 네 아들 네 사랑하는 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 일러 준 한 산 거기서 그를 번제로 드리라", "He said, “Take your son, your only son Isaac, whom you love, and go to the land of Moriah, and offer him there as a burnt offering on one of the mountains of which I shall tell you.”"], "3": ["아브라함이 아침에 일찍이 일어나 나귀에 안장을 지우고 두 종과 그의 아들 이삭을 데리고 번제에 쓸 나무를 쪼개어 가지고 떠나 하나님이 자기에게 일러 주신 곳으로 가더니", "So Abraham rose early in the morning, saddled his donkey, and took two of his young men with him, and his son Isaac. And he cut the wood for the burnt offering and arose and went to the place of which God had told him."], "4": ["제삼일에 아브라함이 눈을 들어 그 곳을 멀리 바라본지라", "On the third day Abraham lifted up his eyes and saw the place from afar."], "5": ["이에 아브라함이 종들에게 이르되 너희는 나귀와 함께 여기서 기다리라 내가 아이와 함께 저기 가서 예배하고 우리가 너희에게로 돌아오리라 하고", "Then Abraham said to his young men, “Stay here with the donkey; I and the boy will go over there and worship and come again to you.”"], "6": ["아브라함이 이에 번제 나무를 가져다가 그의 아들 이삭에게 지우고 자기는 불과 칼을 손에 들고 두 사람이 동행하더니", "And Abraham took the wood of the burnt offering and laid it on Isaac his son. And he took in his hand the fire and the knife. So they went both of them together."], "7": ["이삭이 그 아버지 아브라함에게 말하여 이르되 내 아버지여 하니 그가 이르되 내 아들아 내가 여기 있노라 이삭이 이르되 불과 나무는 있거니와 번제할 어린 양은 어디 있나이까", "And Isaac said to his father Abraham, “My father!” And he said, “Here I am, my son.” He said, “Behold, the fire and the wood, but where is the lamb for a burnt offering?”"], "8": ["아브라함이 이르되 내 아들아 번제할 어린 양은 하나님이 자기를 위하여 친히 준비하시리라 하고 두 사람이 함께 나아가서", "Abraham said, “God will provide for himself the lamb for a burnt offering, my son.” So they went both of them together."], "9": ["하나님이 그에게 일러 주신 곳에 이른지라 이에 아브라함이 그 곳에 제단을 쌓고 나무를 벌여 놓고 그의 아들 이삭을 결박하여 제단 나무 위에 놓고", "When they came to the place of which God had told him, Abraham built the altar there and laid the wood in order and bound Isaac his son and laid him on the altar, on top of the wood."], "10": ["손을 내밀어 칼을 잡고 그 아들을 잡으려 하니", "Then Abraham reached out his hand and took the knife to slaughter his son."], "11": ["여호와의 사자가 하늘에서부터 그를 불러 이르시되 아브라함아 아브라함아 하시는지라 아브라함이 이르되 내가 여기 있나이다 하매", "But the angel of the Lord called to him from heaven and said, “Abraham, Abraham!” And he said, “Here I am.”"], "12": ["사자가 이르시되 그 아이에게 네 손을 대지 말라 그에게 아무 일도 하지 말라 네가 네 아들 네 독자까지도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라", "He said, “Do not lay your hand on the boy or do anything to him, for now I know that you fear God, seeing you have not withheld your son, your only son, from me.”"], "13": ["아브라함이 눈을 들어 살펴본즉 한 숫양이 뒤에 있는데 뿔이 수풀에 걸려 있는지라 아브라함이 가서 그 숫양을 가져다가 아들을 대신하여 번제로 드렸더라", "And Abraham lifted up his eyes and looked, and behold, behind him was a ram, caught in a thicket by his horns. And Abraham went and took the ram and offered it up as a burnt offering instead of his son."], "14": ["아브라함이 그 땅 이름을 여호와 이레라 하였으므로 오늘날까지 사람들이 이르기를 여호와의 산에서 준비되리라 하더라", "So Abraham called the name of that place, “The Lord will provide”; as it is said to this day, “On the mount of the Lord it shall be provided.”"]}}, "jos": {"2": {"9": ["말하되 여호와께서 이 땅을 너희에게 주신 줄을 내가 아노라 우리가 너희를 심히 두려워하고 이 땅 주민들이 다 너희 앞에서 간담이 녹나니", "and said to the men, “I know that the Lord has given you the land, and that the fear of you has fallen upon us, and that all the inhabitants of the land melt away before you."], "10": ["이는 너희가 애굽에서 나올 때에 여호와께서 너희 앞에서 홍해 물을 마르게 하신 일과 너희가 요단 저쪽에 있는 아모리 사람의 두 왕 시혼과 옥에게 행한 일 곧 그들을 전멸시킨 일을 우리가 들었음이니라", "For we have heard how the Lord dried up the water of the Red Sea before you when you came out of Egypt, and what you did to the two kings of the Amorites who were beyond the Jordan, to Sihon and Og, whom you devoted to destruction."], "11": ["우리가 듣자 곧 마음이 녹았고 너희로 말미암아 사람이 정신을 잃었나니 너희의 하나님 여호와는 위로는 하늘에서도 아래로는 땅에서도 하나님이시니라", "And as soon as we heard it, our hearts melted, and there was no spirit left in any man because of you, for the Lord your God, he is God in the heavens above and on the earth beneath."]}}};
var LESSONS34={"mon": {"name": "마음 열기", "tag": "OPEN OUR HEARTS", "title": "말씀 속으로 들어가요!", "en": "Feel the Story!", "color": "#F6D6D1", "ink": "#7A3A35", "teaser": "아브라함과 이삭이 산에 오르는 이야기", "qs": [{"type": "pickmany", "label": "모두 고르기 · 창 22:6", "q": "아브라함과 이삭이 산으로 올라가고 있어요. 말씀에 나온 물건들을 찾아 모두 골라요.", "en": "Abraham and Isaac are walking up the mountain. Choose the things mentioned in the Bible.", "opts": [["나무", "Wood", "wood"], ["불", "Fire", "fire"], ["빵", "Bread", "bread"], ["칼", "Knife", "knife"]], "answer": [0, 1, 3], "ok": "맞아요! 아브라함은 번제 나무와 불, 칼을 가지고 올라갔어요.", "no": "창세기 22장 6절을 다시 읽어 볼까요? 빵은 나오지 않아요."}, {"type": "fill", "label": "써 보기 · 창 22:7", "q": "산을 올라가던 이삭이 아버지에게 질문했어요. 이삭이 한 말을 완성해 보세요.", "en": "Isaac asked his father a question. Fill in the missing word.", "parts": ["“불과 나무는 있거니와 번제할 ", 0, "은 어디 있나이까?”"], "ok": "잘했어요! 이삭은 번제할 어린양이 어디 있는지 물었어요."}, {"type": "match", "label": "순서 맞추기 · 창 22:6-13", "q": "아브라함과 이삭의 이야기를 순서대로 연결해요. 왼쪽을 누르고 알맞은 순서를 오른쪽에서 눌러요.", "en": "Put the events in the correct order. Tap an event on the left, then tap its place in the order on the right.", "left": [["하나님이 준비하신 숫양을 발견했어요.", "They found the ram God provided."], ["아브라함과 이삭이 함께 산에 올라갔어요.", "Abraham and Isaac went up the mountain."], ["이삭이 번제할 어린양이 어디 있는지 물었어요.", "Isaac asked where the lamb was."]], "right": [["첫 번째", "First"], ["두 번째", "Second"], ["세 번째", "Third"]], "answer": [2, 0, 1], "ok": "모두 맞았어요! 산에 올라가고, 이삭이 묻고, 하나님이 준비하신 숫양을 발견했어요."}, {"type": "text", "label": "한두 단어로 쓰기 · 창 22:13", "q": "하나님이 준비하신 숫양을 발견한 아브라함은 어떤 마음이었을까요? 한두 단어로 적어 보세요.", "en": "How do you think Abraham felt when he found the ram God provided? Write one or two words.", "ph": "아브라함의 마음", "ok": "멋져요! 아브라함의 마음을 상상해 봤어요."}]}, "tue": {"name": "말씀 찾기", "tag": "VIEWING WHAT HAS BEEN GIVEN", "title": "말씀에 있는 그대로 찾아요", "en": "Explore the Word.", "color": "#E1DBF8", "ink": "#4F4290", "teaser": "믿음과 함께 일하는 것은?", "qs": [{"type": "single", "label": "고르기 · 22절", "q": "아브라함의 믿음은 무엇과 함께 일했나요? 정답을 골라요.", "en": "What worked together with Abraham's faith? Choose the correct answer.", "opts": [["말", "Words"], ["행함", "Actions"], ["생각", "Thoughts"]], "answer": 1, "ok": "맞아요! 아브라함의 믿음은 행함과 함께 일했어요.", "no": "22절을 다시 읽어 볼까요?"}, {"type": "blanks", "label": "빈칸 채우기 · 22절", "q": "알맞은 말을 골라 빈칸에 넣어 보세요.", "en": "Choose the correct words to fill in the blanks.", "lines": [["믿음이 그의 ", 0, "과 함께 일하고, 행함으로 믿음이 ", 1, "하게 되었느니라."]], "words": ["행함", "온전", "사랑"], "answers": ["행함", "온전"], "ok": "맞아요! 믿음이 행함과 함께 일하고, 행함으로 믿음이 온전하게 되었어요."}, {"type": "single", "label": "고르기 · 23절", "q": "아브라함은 무엇이라고 불렸나요? 알맞은 답을 골라요.", "en": "What was Abraham called? Choose the correct answer.", "opts": [["하나님의 종", "God's servant"], ["하나님의 벗", "God's friend"], ["하나님의 선지자", "God's prophet"]], "answer": 1, "ok": "맞아요! 아브라함은 하나님의 벗이라 칭함을 받았어요.", "no": "23절을 다시 읽어 볼까요?"}, {"type": "match", "label": "짝 맞추기 · 26절", "q": "야고보는 행함이 없는 믿음을 무엇에 비유했나요? 왼쪽을 누르고 알맞은 것을 오른쪽에서 눌러요.", "en": "What does James compare faith without actions to? Tap the left, then tap the matching answer on the right.", "left": [["행함이 없는 믿음", "Faith without actions"]], "right": [["뿌리 없는 나무", "A tree without roots"], ["영혼 없는 몸", "A body without the spirit"]], "answer": [1], "ok": "맞아요! 행함이 없는 믿음은 영혼 없는 몸과 같아요."}]}, "wed": {"name": "숨은 이야기", "tag": "FINDING HIDDEN STORIES", "title": "왜 그렇게 행동했을까요?", "en": "Why Did They Act That Way?", "color": "#DCE7C6", "ink": "#44572A", "teaser": "아브라함과 라합은 왜 그렇게 했을까?", "qs": [{"type": "single", "label": "고르기 · 21-23절", "q": "아브라함은 왜 하나님의 말씀에 순종했을까요? 알맞은 답을 골라요.", "en": "Why did Abraham obey God's Word? Choose the correct answer.", "opts": [["사람들에게 칭찬받고 싶어서", "To receive praise from others."], ["하나님을 믿고 신뢰했기 때문에", "Because he believed and trusted God."], ["자신이 용감하다는 것을 보여주려고", "To show how brave he was."]], "answer": 1, "ok": "맞아요! 아브라함은 하나님을 믿고 신뢰했기 때문에 순종했어요.", "no": "다시 생각해 봐요. 아브라함은 무엇을 믿었을까요?"}, {"type": "single", "label": "고르기 · 25절 · 수 2:9-11", "q": "라합은 왜 위험을 무릅쓰고 정탐꾼들을 도와주었을까요? 알맞은 생각을 골라요.", "en": "Why did Rahab risk her safety to help the spies? Choose the correct thought.", "opts": [["하나님은 참 하나님이시니까!", "Because the Lord is the true God!"], ["정탐꾼들에게 칭찬받고 싶으니까!", "Because I want the spies to praise me!"]], "answer": 0, "ok": "맞아요! 라합은 여호와가 참 하나님이시라고 믿었어요.", "no": "여호수아 2장 9-11절을 다시 읽어 볼까요?"}, {"type": "blanks", "label": "빈칸 채우기 · 21-25절", "q": "아브라함과 라합의 믿음에는 어떤 공통점이 있을까요? 알맞은 말을 골라 빈칸에 넣어 보세요.", "en": "What did Abraham and Rahab have in common? Choose the correct words to fill in the blanks.", "lines": [["두 사람 모두 하나님을 ", 0, "했고, 그 믿음을 ", 1, "으로 나타냈어요."]], "words": ["신뢰", "행동", "말"], "answers": ["신뢰", "행동"], "ok": "맞아요! 두 사람 모두 하나님을 신뢰했고, 그 믿음을 행동으로 나타냈어요."}, {"type": "match", "label": "짝 맞추기 · 21-25절", "q": "아브라함과 라합은 하나님을 믿는 마음을 어떻게 행동으로 나타냈나요? 왼쪽을 누르고 알맞은 행동을 오른쪽에서 눌러요.", "en": "How did Abraham and Rahab show their trust in God through their actions? Tap a person on the left, then tap the matching action.", "left": [["아브라함", "Abraham"], ["라합", "Rahab"]], "right": [["정탐꾼들을 도와주었어요.", "Helped the spies."], ["하나님의 말씀에 순종했어요.", "Obeyed God's Word."]], "answer": [1, 0], "ok": "모두 맞았어요! 아브라함은 하나님의 말씀에 순종했고, 라합은 정탐꾼들을 도와주었어요."}]}, "thu": {"name": "하나님 마음", "tag": "ENCOUNTERING THE HEART OF GOD", "title": "하나님의 마음을 알아가요!", "en": "Getting to Know God's Heart!", "color": "#FBE3D2", "ink": "#8A4A22", "teaser": "하나님은 어떤 믿음을 귀하게 여기실까?", "qs": [{"type": "single", "label": "고르기 · 23절", "q": "하나님은 아브라함의 믿음을 의로 여기셨어요. 이것은 하나님께서 무엇을 중요하게 여기신다는 뜻일까요?", "en": "God counted Abraham's faith as righteousness. What does this tell us is important to God?", "opts": [["의로 여기셨어요.", "Counted it as righteousness."], ["소중하지 않게 여기셨어요.", "Did not value his faith."], ["믿음이 없다고 하셨어요.", "Said he had no faith."]], "answer": 0, "ok": "맞아요! 하나님은 아브라함의 믿음을 의로 여기셨어요.", "no": "23절을 다시 읽어 볼까요?"}, {"type": "single", "label": "고르기 · 23절", "q": "하나님은 아브라함을 ‘하나님의 벗’이라고 부르셨어요. 이것은 하나님과 아브라함이 어떤 관계였다는 뜻일까요?", "en": "Abraham was called “God's friend.” What does this tell us about his relationship with God?", "opts": [["서로 믿고 가까이하는 관계", "A close relationship built on trust."], ["서로 모르는 사이", "A relationship between strangers."], ["서로 경쟁하는 관계", "A relationship between rivals."]], "answer": 0, "ok": "맞아요! 하나님과 아브라함은 서로 믿고 가까이하는 관계였어요.", "no": "‘벗’은 어떤 사이일까요? 다시 생각해 봐요."}, {"type": "pickmany", "label": "고르기 · 22절", "q": "하나님은 우리의 믿음이 어떻게 나타나기를 원하실까요? 알맞은 그림을 골라요.", "en": "How does God want our faith to be shown? Choose the correct picture.", "opts": [["말로만 믿어요.", "Only saying, “I believe.”", "talk"], ["믿음으로 행동해요.", "Putting faith into action.", "share"]], "answer": [1], "ok": "맞아요! 하나님은 우리의 믿음이 행동으로 나타나기를 원하세요.", "no": "22절을 다시 읽어 볼까요?"}, {"type": "single", "label": "고르기 · 26절", "q": "야고보는 행함이 없는 믿음을 영혼 없는 몸에 비유했어요. 하나님께서 기뻐하시는 믿음은 어떤 믿음일까요?", "en": "James compares faith without actions to a body without the spirit. What kind of faith pleases God?", "opts": [["행함이 없는 믿음", "Faith without actions."], ["행함이 함께하는 살아 있는 믿음", "Living faith shown through actions."]], "answer": 1, "ok": "맞아요! 하나님은 행함이 함께하는 살아 있는 믿음을 기뻐하세요.", "no": "26절을 다시 읽어 볼까요?"}]}, "fri": {"name": "내 삶으로", "tag": "INTO MY LIFE", "title": "나는 어떻게 살아야 할까요?", "en": "How Should I Live?", "color": "#FBEBB8", "ink": "#6E5410", "teaser": "믿음을 행동으로 옮기려면?", "qs": [{"type": "multi", "free": true, "label": "모두 골라 보기", "q": "나는 평소 하나님을 믿는 마음을 어떻게 나타내고 있나요? 해당하는 것을 모두 골라요.", "en": "How do you show your faith in God? Check all that apply.", "opts": [["하나님의 말씀을 따라 행동해요.", "I put God's Word into action."], ["도움이 필요한 사람을 도와요.", "I help people in need."], ["다른 사람을 사랑하고 배려해요.", "I show love and care for others."], ["아직 행동으로 옮기기 어려울 때가 많아요.", "Sometimes it's hard for me to put my faith into action."]], "answer": [0, 1, 2, 3], "ok": "좋아요! 하나님을 믿는 마음을 어떻게 나타내는지 돌아봤어요."}, {"type": "blanks", "label": "빈칸 채우기 · 약 2:1-5", "q": "하나님은 가난한 사람도 믿음에 부요하게 하셨어요. 우리는 사람들을 어떻게 대해야 할까요?", "en": "God has made the poor rich in faith. How should we treat others?", "lines": [["우리는 사람들을 ", 0, " 않고, ", 1, " 대해야 해요."]], "words": ["차별하지", "사랑하며", "무시하며"], "answers": ["차별하지", "사랑하며"], "ok": "맞아요! 우리는 사람들을 차별하지 않고, 사랑하며 대해야 해요."}, {"type": "single", "label": "고르기", "q": "하나님의 말씀대로 행동하기 어려울 때, 나는 어떻게 해야 할까요?", "en": "What should I do when it's hard to put God's Word into action?", "opts": [["포기해요.", "Give up."], ["하나님께 도움을 구하고 다시 노력해요.", "Ask God for help and try again."], ["다른 사람이 하기를 기다려요.", "Wait for someone else to do it."]], "answer": 1, "ok": "맞아요! 어려울 때는 하나님께 도움을 구하고 다시 노력해요.", "no": "다시 생각해 봐요. 어려울 때 누구에게 도움을 구할 수 있을까요?"}, {"type": "fill", "label": "써 보기", "q": "이번 주에 하나님을 믿는 마음으로 실천하고 싶은 일 한 가지를 적어 보세요.", "en": "Write one thing you want to do this week to show your faith in God.", "parts": ["나는 하나님을 믿기 때문에 ", 0, " 실천할 거예요!"], "ok": "멋져요! 이번 주에 꼭 실천해 봐요."}]}};
var LESSONS34_EN={"mon": {"name": "Open Hearts", "title": "Feel the Story!", "teaser": "Abraham and Isaac go up the mountain", "qs": [{"label": "Choose all · Gen 22:6", "ok": "That’s right! Abraham took the wood, the fire, and the knife.", "no": "Let’s read Genesis 22:6 again. There is no bread.", "q": "Abraham and Isaac are walking up the mountain. Choose the things mentioned in the Bible."}, {"label": "Write · Gen 22:7", "ok": "Well done! Isaac asked where the lamb for the burnt offering was.", "parts": ["“We have the fire and wood, but where is the ", 0, "?”"], "q": "Isaac asked his father a question. Fill in the missing word."}, {"label": "Put in order · Gen 22:6–13", "ok": "All correct! They went up the mountain, Isaac asked, and they found the ram God provided.", "q": "Put the events in the correct order. Tap an event on the left, then tap its place in the order on the right."}, {"label": "Write one or two words · Gen 22:13", "ok": "Wonderful! You imagined how Abraham felt.", "ph": "How Abraham felt", "q": "How do you think Abraham felt when he found the ram God provided? Write one or two words."}]}, "tue": {"name": "Find the Word", "title": "Explore the Word.", "teaser": "What worked with Abraham’s faith?", "qs": [{"label": "Choose · v. 22", "ok": "That’s right! Abraham’s faith worked together with his actions.", "no": "Let’s read verse 22 again.", "q": "What worked together with Abraham's faith? Choose the correct answer."}, {"label": "Fill in the blanks · v. 22", "ok": "That’s right! Faith worked together with his actions, and by his actions his faith was made complete.", "lines": [["His faith worked together with his ", 0, ", and by his actions his faith was made ", 1, "."]], "wordsEn": ["actions", "complete", "love"], "q": "Choose the correct words to fill in the blanks."}, {"label": "Choose · v. 23", "ok": "That’s right! Abraham was called God’s friend.", "no": "Let’s read verse 23 again.", "q": "What was Abraham called? Choose the correct answer."}, {"label": "Match · v. 26", "ok": "That’s right! Faith without actions is like a body without the spirit.", "q": "What does James compare faith without actions to? Tap the left, then tap the matching answer on the right."}]}, "wed": {"name": "Hidden Story", "title": "Why Did They Act That Way?", "teaser": "Why did Abraham and Rahab act?", "qs": [{"label": "Choose · vv. 21–23", "ok": "That’s right! Abraham obeyed because he believed and trusted God.", "no": "Let’s think again. What did Abraham believe?", "q": "Why did Abraham obey God's Word? Choose the correct answer."}, {"label": "Choose · v. 25 · Josh 2:9–11", "ok": "That’s right! Rahab believed the Lord is the true God.", "no": "Let’s read Joshua 2:9–11 again.", "q": "Why did Rahab risk her safety to help the spies? Choose the correct thought."}, {"label": "Fill in the blanks · vv. 21–25", "ok": "That’s right! Both trusted God and showed their faith through their actions.", "lines": [["They both ", 0, " God and showed their faith through their ", 1, "."]], "wordsEn": ["trusted", "actions", "words"], "q": "What did Abraham and Rahab have in common? Choose the correct words to fill in the blanks."}, {"label": "Match · vv. 21–25", "ok": "All correct! Abraham obeyed God’s Word, and Rahab helped the spies.", "q": "How did Abraham and Rahab show their trust in God through their actions? Tap a person on the left, then tap the matching action."}]}, "thu": {"name": "God's Heart", "title": "Getting to Know God's Heart!", "teaser": "What kind of faith does God value?", "qs": [{"label": "Choose · v. 23", "ok": "That’s right! God counted Abraham’s faith as righteousness.", "no": "Let’s read verse 23 again.", "q": "God counted Abraham's faith as righteousness. What does this tell us is important to God?"}, {"label": "Choose · v. 23", "ok": "That’s right! God and Abraham had a close relationship built on trust.", "no": "What kind of relationship is a friend? Let’s think again.", "q": "Abraham was called “God's friend.” What does this tell us about his relationship with God?"}, {"label": "Choose · v. 22", "ok": "That’s right! God wants our faith to be shown through our actions.", "no": "Let’s read verse 22 again.", "q": "How does God want our faith to be shown? Choose the correct picture."}, {"label": "Choose · v. 26", "ok": "That’s right! God is pleased with living faith shown through actions.", "no": "Let’s read verse 26 again.", "q": "James compares faith without actions to a body without the spirit. What kind of faith pleases God?"}]}, "fri": {"name": "Into My Life", "title": "How Should I Live?", "teaser": "How can I put my faith into action?", "qs": [{"label": "Check all that apply", "ok": "Good! You thought about how you show your faith.", "q": "How do you show your faith in God? Check all that apply."}, {"label": "Fill in the blanks · Jas 2:1–5", "ok": "That’s right! We should treat others without favoritism and with love.", "lines": [["We should treat others ", 0, " and ", 1, "."]], "wordsEn": ["without favoritism", "with love", "by ignoring"], "q": "God has made the poor rich in faith. How should we treat others?"}, {"label": "Choose", "ok": "That’s right! When it’s hard, we ask God for help and try again.", "no": "Let’s think again. Who can we ask for help?", "q": "What should I do when it's hard to put God's Word into action?"}, {"label": "Write", "ok": "Great! Try it this week.", "parts": ["Because I trust God, I will ", 0, "."], "q": "Write one thing you want to do this week to show your faith in God."}]}};
